import pytest
from candidate import filter_by_substring


class TestFilterBySubstringNormalCases:
    def test_filters_strings_containing_substring(self):
        assert filter_by_substring(['abc', 'bacd', 'cde', 'array'], 'a') == ['abc', 'bacd', 'array']

    def test_filters_all_when_all_contain_substring(self):
        assert filter_by_substring(['apple', 'apricot', 'application'], 'app') == ['apple', 'apricot', 'application']

    def test_filters_none_when_no_string_contains_substring(self):
        assert filter_by_substring(['xyz', 'abc', 'def'], 'q') == []

    def test_substring_at_beginning_of_string(self):
        assert filter_by_substring(['hello', 'world'], 'he') == ['hello']

    def test_substring_at_end_of_string(self):
        assert filter_by_substring(['hello', 'world'], 'lo') == ['hello']

    def test_substring_in_middle_of_string(self):
        assert filter_by_substring(['hello', 'world'], 'll') == ['hello']

    def test_single_character_substring(self):
        assert filter_by_substring(['a', 'b', 'ab', 'ba'], 'b') == ['b', 'ab', 'ba']

    def test_substring_equal_to_entire_string(self):
        assert filter_by_substring(['abc', 'abcd', 'xabc'], 'abc') == ['abc', 'abcd', 'xabc']

    def test_preserves_original_order(self):
        assert filter_by_substring(['z', 'a', 'm', 'b', 'c'], 'a') == ['a']

    def test_multiple_occurrences_of_substring_in_one_string(self):
        assert filter_by_substring(['ababab', 'cdcd', 'ab'], 'ab') == ['ababab', 'ab']

    def test_single_element_list_with_match(self):
        assert filter_by_substring(['test'], 'est') == ['test']

    def test_single_element_list_without_match(self):
        assert filter_by_substring(['test'], 'xyz') == []


class TestFilterBySubstringEmptyInputs:
    def test_empty_list_returns_empty_list(self):
        assert filter_by_substring([], 'a') == []

    def test_empty_substring_returns_all_strings(self):
        assert filter_by_substring(['abc', 'def', 'ghi'], '') == ['abc', 'def', 'ghi']

    def test_empty_list_with_empty_substring(self):
        assert filter_by_substring([], '') == []


class TestFilterBySubstringEdgeCases:
    def test_substring_longer_than_all_strings(self):
        assert filter_by_substring(['a', 'ab', 'abc'], 'abcdef') == []

    def test_substring_same_length_as_one_string(self):
        assert filter_by_substring(['abc', 'ab', 'abcd'], 'abc') == ['abc', 'abcd']

    def test_unicode_strings(self):
        assert filter_by_substring(['héllo', 'wörld', 'café'], 'é') == ['héllo', 'café']

    def test_strings_with_special_characters(self):
        assert filter_by_substring(['a!b', 'a*b', 'a+b'], 'a') == ['a!b', 'a*b', 'a+b']

    def test_strings_with_whitespace(self):
        assert filter_by_substring(['hello world', 'helloworld', '  spaces  '], '  ') == ['hello world', '  spaces  ']

    def test_case_sensitive_by_default(self):
        assert filter_by_substring(['Apple', 'apple', 'APPLE', 'banana'], 'apple') == ['apple']

    def test_substring_with_whitespace(self):
        assert filter_by_substring(['hello world', 'helloworld', 'hello  world'], ' ') == ['hello world', 'hello  world']

    def test_emoji_in_strings(self):
        assert filter_by_substring(['🎉party', 'no party', 'party 🎊'], '🎉') == ['🎉party']

    def test_numeric_strings(self):
        assert filter_by_substring(['123', '456', '789', '1234'], '12') == ['123', '1234']

    def test_substring_is_single_space(self):
        assert filter_by_substring(['a b', 'ab', '  c'], ' ') == ['a b', '  c']

    def test_duplicate_strings_in_list(self):
        assert filter_by_substring(['abc', 'abc', 'def'], 'abc') == ['abc', 'abc']


class TestFilterBySubstringErrorHandling:
    def test_none_list_raises_type_error(self):
        with pytest.raises(TypeError):
            filter_by_substring(None, 'a')

    def test_none_substring_raises_type_error(self):
        with pytest.raises(TypeError):
            filter_by_substring(['abc'], None)

    def test_none_in_list_raises_type_error(self):
        with pytest.raises(TypeError):
            filter_by_substring([None, 'abc'], 'a')

    def test_integer_substring_raises_type_error(self):
        with pytest.raises(TypeError):
            filter_by_substring(['abc', 'def'], 123)

    def test_integer_in_list_raises_type_error(self):
        with pytest.raises(TypeError):
            filter_by_substring([123, 'abc'], 'a')


class TestFilterBySubstringWithUnusualInputs:
    def test_list_with_empty_string_element(self):
        assert filter_by_substring(['', 'abc', 'def'], 'a') == ['abc']

    def test_list_with_only_empty_string(self):
        assert filter_by_substring([''], '') == ['']

    def test_list_with_only_empty_string_nonempty_substring(self):
        assert filter_by_substring([''], 'a') == []

    def test_string_with_null_bytes(self):
        assert filter_by_substring(['a\x00b', 'a\x00c', 'xyz'], '\x00') == ['a\x00b', 'a\x00c']

    def test_tab_and_newline_in_substring(self):
        assert filter_by_substring(['a\tb', 'a\nb', 'ab'], '\t') == ['a\tb']

    def test_backslash_in_substring(self):
        assert filter_by_substring(['a\\b', 'a/b', 'ab'], '\\') == ['a\\b']

    def test_long_string_list(self):
        strings = [f"prefix_{i}_suffix" for i in range(1000)]
        result = filter_by_substring(strings, 'prefix_999_')
        assert result == ['prefix_999_suffix']
